import heapq

def match(orders):
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    info = {}       # id -> [side, price, qty] for resting orders currently active
    seq_counter = 0
    trades = []

    def add_resting(oid, side, price, qty, seq):
        info[oid] = [side, price, qty]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def try_match(incoming_side, incoming_price, incoming_qty, incoming_id, is_market):
        trades_local = []
        if incoming_side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while incoming_qty > 0 and heap:
            top = heap[0]
            if incoming_side == 'buy':
                price, seq, rid = top
            else:
                negprice, seq, rid = top
                price = -negprice

            if rid not in info:
                heapq.heappop(heap)
                continue

            r_side, r_price, r_qty = info[rid]
            if r_qty <= 0:
                heapq.heappop(heap)
                if rid in info:
                    del info[rid]
                continue

            if not is_market:
                if incoming_side == 'buy' and incoming_price < r_price:
                    break
                if incoming_side == 'sell' and incoming_price > r_price:
                    break

            trade_qty = min(incoming_qty, r_qty)
            if incoming_side == 'buy':
                trades_local.append([incoming_id, rid, r_price, trade_qty])
            else:
                trades_local.append([rid, incoming_id, r_price, trade_qty])

            incoming_qty -= trade_qty
            r_qty -= trade_qty
            info[rid][2] = r_qty

            if r_qty == 0:
                heapq.heappop(heap)
                if rid in info:
                    del info[rid]
            # if r_qty > 0, incoming_qty must be 0 now, loop will exit naturally

        return incoming_qty, trades_local

    for o in orders:
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            if oid in info:
                del info[oid]
            continue

        seq_counter += 1

        if typ == 'limit':
            _, oid, side, price, qty = o
            remaining, trades_local = try_match(side, price, qty, oid, False)
            trades.extend(trades_local)
            if remaining > 0:
                add_resting(oid, side, price, remaining, seq_counter)

        elif typ == 'ioc':
            _, oid, side, price, qty = o
            remaining, trades_local = try_match(side, price, qty, oid, False)
            trades.extend(trades_local)
            # remainder discarded, not added to book

        elif typ == 'market':
            _, oid, side, qty = o
            remaining, trades_local = try_match(side, None, qty, oid, True)
            trades.extend(trades_local)
            # remainder discarded

    return trades

